const { validateRecipient, validateMessage } = require('./validation');
const buildEnvelope = require('./envelope');
const createRateLimiter = require('./rateLimiter');

function composeNotifier(strategy, options = {}) {
  const {
    channel,
    defaultMaxPerHour,
    transportKey,
    transportLabel,
    configure = () => ({}),
    validateUser: validateChannelUser = () => {},
    bypassesThrottle = () => false,
    optOutReason = () => null,
    format: formatChannel
  } = strategy;

  const transport = options.transport || {};
  const now = options.now || (() => new Date());
  const defaultLocale = options.defaultLocale || 'en-US';
  const rateLimiter = createRateLimiter({
    channel,
    store: options.throttleStore || new Map(),
    now,
    maxPerHour: options.maxPerHour || defaultMaxPerHour
  });
  const settings = configure(options);

  function validateUser(user) {
    validateRecipient(user);
    validateChannelUser(user);
  }

  function shouldThrottle(user, message, sendOptions = {}) {
    if (bypassesThrottle(user, message, sendOptions)) {
      return { throttled: false };
    }

    if (!sendOptions.force && message.priority !== 'urgent') {
      const limit = rateLimiter.check(user, message);
      if (limit.throttled) {
        return limit;
      }
    }

    const reason = optOutReason(user, message);
    if (reason) {
      return { throttled: true, reason, retryAt: null };
    }

    return { throttled: false };
  }

  function format(user, message, sendOptions = {}) {
    const envelope = buildEnvelope({ channel, now, defaultLocale }, user, message, sendOptions);
    return {
      ...envelope,
      ...formatChannel(envelope, { user, message, options: sendOptions, settings, now })
    };
  }

  async function deliver(payload) {
    if (typeof transport[transportKey] !== 'function') {
      throw new Error(`${transportLabel} transport is not configured`);
    }
    await transport[transportKey](payload);
  }

  async function send(user, message, sendOptions = {}) {
    validateUser(user);
    validateMessage(message);

    const throttle = shouldThrottle(user, message, sendOptions);
    if (throttle.throttled) {
      return {
        channel,
        status: 'throttled',
        reason: throttle.reason,
        retryAt: throttle.retryAt,
        userId: user.id
      };
    }

    const payload = format(user, message, sendOptions);
    await deliver(payload);
    rateLimiter.record(user, message);

    return {
      channel,
      status: 'sent',
      userId: user.id,
      id: payload.id,
      preview: payload.preview
    };
  }

  return {
    channel,
    send,
    validateUser,
    validateMessage,
    shouldThrottle,
    format,
    deliver,
    recordDelivery: rateLimiter.record
  };
}

module.exports = composeNotifier;

