const composeNotifier = require('./composeNotifier');

function footerFor(user, message, unsubscribeBaseUrl) {
  if (message.category === 'transactional' || message.category === 'security') {
    return `Sent to ${user.email} because of recent account activity.`;
  }
  const url = `${unsubscribeBaseUrl}?user=${encodeURIComponent(user.id)}`;
  return `You can unsubscribe at ${url}.`;
}

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const emailChannel = {
  channel: 'email',
  defaultMaxPerHour: 8,
  transportKey: 'email',
  transportLabel: 'email',

  configure(options) {
    return {
      from: options.from || 'noreply@example.com',
      replyTo: options.replyTo || 'support@example.com',
      unsubscribeBaseUrl: options.unsubscribeBaseUrl || 'https://example.com/unsubscribe'
    };
  },

  validateUser(user) {
    if (!user.email || !user.email.includes('@')) {
      throw new TypeError('user.email is required for email notifications');
    }
  },

  optOutReason(user, message) {
    if (message.category === 'marketing' && !user.emailOptIn) {
      return 'user has not opted into marketing email';
    }
    return null;
  },

  format(envelope, { user, message, settings }) {
    const subjectPrefix = message.category === 'security' ? '[Action Required] ' : '';
    const footer = footerFor(user, message, settings.unsubscribeBaseUrl);

    return {
      to: user.email,
      from: settings.from,
      replyTo: settings.replyTo,
      subject: `${subjectPrefix}${envelope.title}`,
      text: `${envelope.body}\n\n${footer}`,
      html: `<h1>${escapeHtml(envelope.title)}</h1><p>${escapeHtml(envelope.body)}</p><footer>${escapeHtml(footer)}</footer>`,
      preview: envelope.body.slice(0, 90)
    };
  }
};

function createEmailNotifier(options = {}) {
  return composeNotifier(emailChannel, options);
}

module.exports = createEmailNotifier;

