const composeNotifier = require('./composeNotifier');

function truncate(value, maxLength) {
  if (value.length <= maxLength) {
    return value;
  }
  return `${value.slice(0, maxLength - 1)}…`;
}

const smsChannel = {
  channel: 'sms',
  defaultMaxPerHour: 4,
  transportKey: 'sms',
  transportLabel: 'sms',

  configure(options) {
    return {
      senderId: options.senderId || 'APP',
      segmentLength: options.segmentLength || 140
    };
  },

  validateUser(user) {
    if (!user.phone || !/^\+[1-9]\d{6,14}$/.test(user.phone)) {
      throw new TypeError('user.phone must be E.164 for SMS notifications');
    }
  },

  optOutReason(user, message) {
    if (message.category === 'marketing' && !user.smsOptIn) {
      return 'user has not opted into marketing SMS';
    }
    return null;
  },

  format(envelope, { user, message, settings }) {
    const prefix = message.priority === 'urgent' ? 'URGENT: ' : '';
    const composed = `${prefix}${envelope.title} - ${envelope.body}`;
