    return {
      workspace: user.slackWorkspace || settings.defaultWorkspace,
      channel,
      threadTs: options.threadTs || null,
      text,
      blocks: blocksFor(envelope, mention),
      preview: text.replace(/\*/g, '').slice(0, 120)
    };
  }
};

function createSlackNotifier(options = {}) {
  return composeNotifier(slackChannel, options);
}

