const composeNotifier = require('./composeNotifier');

const inAppChannel = {
  channel: 'inapp',
  defaultMaxPerHour: 50,
  transportKey: 'inapp',
  transportLabel: 'in-app',

  configure(options) {
    return {
      defaultIcon: options.defaultIcon || 'bell',
      defaultAction: options.defaultAction || '/notifications'
    };
  },

  validateUser(user) {
    if (user.disabledInApp) {
      throw new TypeError('in-app notifications are disabled for this user');
    }
  },

  bypassesThrottle(user, message) {
    return message.category === 'security';
  },

  format(envelope, { user, message, options, settings, now }) {
    const expiresInHours = options.expiresInHours || (message.priority === 'urgent' ? 72 : 168);
    const expiresAt = new Date(now().getTime() + expiresInHours * 60 * 60 * 1000);

    return {
      userId: user.id,
      icon: message.icon || settings.defaultIcon,
      actionUrl: options.actionUrl || message.actionUrl || settings.defaultAction,
      read: false,
      expiresAt: expiresAt.toISOString(),
      preview: envelope.title
    };
  }
};

function createInAppNotifier(options = {}) {
  return composeNotifier(inAppChannel, options);
}

module.exports = createInAppNotifier;

