const createEmailNotifier = require('./EmailNotifier');
const createSmsNotifier = require('./SmsNotifier');
const createSlackNotifier = require('./SlackNotifier');
const createInAppNotifier = require('./InAppNotifier');

const registry = {
  email: createEmailNotifier,
  sms: createSmsNotifier,
  slack: createSlackNotifier,
  inapp: createInAppNotifier
};

function createNotifier(channel, options = {}) {
  const createChannelNotifier = registry[channel];
  if (!createChannelNotifier) {
    throw new TypeError(`unknown notification channel: ${channel}`);
  }
  return createChannelNotifier(options);
}

function createAllNotifiers(options = {}) {
  return Object.keys(registry).reduce((all, channel) => {
    all[channel] = createNotifier(channel, options);
    return all;
  }, {});
}

module.exports = {
  createNotifier,
  createAllNotifiers,
  registry
};

